import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Lineage","description":"","frontmatter":{"title":"Lineage"},"headers":[],"relativePath":"api/reference/lineage.md","filePath":"api/reference/lineage.md"}`),a={name:`api/reference/lineage.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="lineage" tabindex="-1">Lineage <a class="header-anchor" href="#lineage" aria-label="Permalink to “Lineage”">​</a></h1><div><p>Operations of the tag <strong>Lineage</strong> implemented in this release. Generated from <code>api/openapi.yaml</code>; planned operations are not listed.</p><h2 id="queryLineage" tabindex="-1">Data lineage of a data object or a system (UC-08, US-065, REQ-062) <a class="header-anchor" href="#queryLineage" aria-label="Permalink to “Data lineage of a data object or a system (UC-08, US-065, REQ-062)”">​</a></h2><p><code>POST /views/lineage/query</code> · <code>queryLineage</code></p><p>Walks the active data flows from a start element: from a data object over the flows that carry it, from a system hop by hop. <code>direction</code> is <code>downstream</code>, <code>upstream</code>, <code>both</code> (the default, the union of both walks) or <code>impact</code> (<code>downstream</code> with <code>impact</code> true on each node). <code>maxDepth</code> is 1 to 100 (default 50); at most 5000 nodes and 10000 edges are returned, <code>truncated</code> says that there are more; a filter <code>metatypeIds</code> of at most 50 metatypes keeps only the nodes of them and their subtypes, the edges stay. The tasks of the data associations of a data object join at depth 1, writers upstream and readers downstream, when the data-input and data-output parts of the lineage model are set. Deleted entities are left out.</p><p>400 for a missing <code>startEntityId</code>, a value out of range, more than 50 <code>metatypeIds</code> or a <code>dataObjectId</code> with a data object start; 404 for an unknown or deleted start; 422 naming <code>metatypeIds</code> for an unknown metatype, <code>dataObjectId</code> for an entity that is no active data object, <code>startEntityId</code> for a connection; 422 <code>LINEAGE_MODEL_INCOMPLETE</code> naming <code>lineageModel</code> when the data-object, data-flow or carries-data part is unset. The only property value returned is &quot;Transformation type&quot; of a data output association, under property visibility (<code>transformationRestricted</code>); a value read through an override role writes one <code>property-override-access</code> event per query with the channel <code>lineage</code>. A <code>POST</code> because the filter list can be long; it only reads and is not audited otherwise.</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: LineageQuery</li></ul><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The lineage</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>422</td><td>An unknown metatype, a <code>dataObjectId</code> that is no data object, a connection as start, or an incomplete lineage model (<code>errors[].code</code> <code>LINEAGE_MODEL_INCOMPLETE</code>, <code>field</code> <code>lineageModel</code>)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};